    // Every seed record below is upserted by a fixed id instead of overwriting
    // the whole collection with `saveAll` — that way, if this ever runs more
    // than once (e.g. a future schema change bumps SEED_FLAG again), it can
    // only touch these specific demo records and never wipes a real account,
    // a real student's progress, or anyone else's stars/badges/trophies.
    this.db.upsert(COLLECTIONS.users, trainer);
    this.db.upsert(COLLECTIONS.modules, module);
    this.db.upsert(COLLECTIONS.modules, identityModule);
    this.db.upsert(COLLECTIONS.modules, confidenceModule);
    this.db.upsert(COLLECTIONS.modules, planningModule);
    this.db.upsert(COLLECTIONS.modules, strengthMatchModule);
    this.db.upsert(COLLECTIONS.modules, empathyModule);
    this.db.upsert(COLLECTIONS.modules, respectModule);
    this.db.upsert(COLLECTIONS.modules, listeningModule);
    this.db.upsert(COLLECTIONS.modules, speakingModule);
    this.db.upsert(COLLECTIONS.modules, expressionModule);
    this.db.upsert(COLLECTIONS.modules, etiquetteModule);
    this.db.upsert(COLLECTIONS.modules, habitsModule);

